#include <bits/stdc++.h>
using namespace std;
#define int long long
int n; 

int eval(int i, int mid, vector<int> &pref){
    int i2 = n-i-mid;
    int idx = i;
    int idx2 = i+2*mid;
    int idx3 = idx2+3*i2;
    
    int sum1 = pref[idx];
    int sum2 = pref[idx2] - pref[idx];
    int sum3 = pref[idx3] - pref[idx2];
    
    
    return 6*sum1 + 4 * sum2 + 3 * sum3;
}


int func(vector<int> &a){
    vector<int> pref(3*n + 1, 0);
    for(int i = 0; i < 3*n; i++){
        pref[i+1] = pref[i]+a[i];
    }
    
    int ans = 0; 
    for(int i = 0; i < n+1; i++){
        int m = n - i;
        int low = 0, high = m, besti = 0;
        while(low <= high){
            int mid = low + (high - low)/2;
            if(mid == 0){
                besti = max(besti, mid);
                low = mid+1;
                continue;
            }
            int prev = eval(i, mid - 1, pref);
            int cur = eval(i, mid, pref);
            
            if(cur >= prev){
                besti = mid;
                low = mid+1;
            }else{
                high = mid - 1;
            }
        }
        ans = max(ans, eval(i, besti, pref));
    }
    return ans;
}

void solve(){
    cin >> n; 
    vector<int> a(n*3);
    
    for(int i = 0;  i < 3*n; i++){
        cin >> a[i];
    }
    
    sort(a.rbegin(), a.rend());
    
    cout << func(a) << "\n";
}

signed main() {
	// your code goes here
    ios::sync_with_stdio(0);
    cin.tie(0);
    
    int t; 
    t = 1;
    cin >> t; 
    while(t--){
        solve();
    }
}
